from __future__ import annotations

from typing import TYPE_CHECKING

import numpy as np
import pandas as pd
from numpy.typing import NDArray
from shapely.geometry import Polygon

if TYPE_CHECKING:
    from scadpy.d2.shape import Shape


def map_shape_to_shape_with_vertex_coordinates[S: Shape](
    shape: S, vertex_coordinates: NDArray[np.float64]
) -> S:
    from scadpy.core.part import Part

    vertices = pd.DataFrame(
        {
            "coordinate_x": vertex_coordinates[:, 0],
            "coordinate_y": vertex_coordinates[:, 1],
            "part_index": shape.vertex_to_part,
            "ring_index": shape.vertex_ring_indices,
        }
    )
    part_colors = shape.part_colors
    ring_types = shape.ring_types

    parts = []
    for part_index, part_vertices in vertices.groupby(by="part_index"):
        exterior = None
        interiors = []
        color = list(part_colors[part_index])

        for ring_index, ring_vertices in part_vertices.groupby(by="ring_index"):
            ring_type = ring_types[ring_index]
            coordinates = ring_vertices[["coordinate_x", "coordinate_y"]].values
            if ring_type == "exterior":
                exterior = coordinates
            else:
                interiors.append(coordinates)
        parts.append(
            Part[Polygon].from_geometry(
                Polygon(shell=exterior, holes=interiors),
                color,
            )
        )

    return shape.from_parts(parts)

