from __future__ import annotations

from typing import TYPE_CHECKING

import numpy as np
import pandas as pd
from numpy.typing import NDArray
from trimesh import Trimesh

if TYPE_CHECKING:
    from scadpy.d3.solid import Solid


def map_solid_to_solid_with_vertex_coordinates[S: Solid](
    solid: S, vertex_coordinates: NDArray[np.float64]
) -> S:
    from scadpy.core.part import Part

    vertices = pd.DataFrame(
        {
            "coordinate_x": vertex_coordinates[:, 0],
            "coordinate_y": vertex_coordinates[:, 1],
            "coordinate_z": vertex_coordinates[:, 2],
            "part_index": solid.vertex_to_part,
        }
    )
    part_colors = solid.part_colors

    parts = []
    for part_index, part_vertices in vertices.groupby(by="part_index"):
        part_vertex_coordinates = part_vertices[
            ["coordinate_x", "coordinate_y", "coordinate_z"]
        ].values

        color = list(part_colors[part_index])

        parts.append(
            Part[Trimesh].from_geometry(
                Trimesh(
                    vertices=part_vertex_coordinates,
                    faces=solid._parts[part_index].geometry.faces,
                ),
                color,
            )
        )

    return solid.from_parts(parts)

