from __future__ import annotations

from collections.abc import Iterable, Sequence
from functools import cached_property
from typing import TYPE_CHECKING, Any, Self, override

from scadpy.color.constants import BLACK

if TYPE_CHECKING:
    from scadpy.color import Color
    from scadpy.core.part import Part

import numpy as np
from IPython.core.display import HTML
from numpy.typing import NDArray
from trimesh import Trimesh
from trimesh.boolean import boolean_manifold  # pyright: ignore[reportUnknownVariableType]
from typeguard import typechecked

from scadpy.core.assembly import (
    Assembly,
    ConcatableAssembly,
    ExcludableAssembly,
    IntersectableAssembly,
    RenderableAssembly,
    SubtractableAssembly,
    UnifiableAssembly,
    VertexableAssembly,
)


@typechecked
class Solid(
    Assembly[Trimesh],
    ConcatableAssembly[Trimesh],
    IntersectableAssembly[Trimesh],
    ExcludableAssembly[Trimesh],
    RenderableAssembly,
    SubtractableAssembly[Trimesh],
    VertexableAssembly[Trimesh],
    UnifiableAssembly[Trimesh],
):
    def __init__(self, *args: Any, **kwargs: Any) -> None:  # pyright: ignore[reportExplicitAny, reportAny]
        super().__init__(*args, **kwargs)

    @classmethod
    @override
    def dimensions(cls) -> int:
        return 3

    #############
    # exporters #
    #############

    @override
    def to_html(self: Self) -> HTML:
        from scadpy.d3.solid import map_solid_to_html

        return map_solid_to_html(solid=self)

    ################
    # combinations #
    ################

    @classmethod
    @override
    def _are_parts_intersecting(
        cls: type[Self], part1: Part[Trimesh], part2: Part[Trimesh]
    ) -> bool:
        return bool(
            boolean_manifold(  # pyright: ignore[reportAny]
                [part1.geometry, part2.geometry],
                operation="intersection",
                check_volume=False,
            ).volume
            != 0
        )

    @classmethod
    @override
    def _intersect_parts(cls: type[Self], parts: Sequence[Part[Trimesh]]) -> Self:
        from scadpy.core.part import Part, intersect_parts

        return intersect_parts(
            parts=parts,
            get_part_color=lambda p: p.color,
            get_part_magnitude=lambda p: p.geometry.area,  # pyright: ignore[reportAny]
            get_part_bounds=cls._get_part_bounds,
            are_parts_intersecting=cls._are_parts_intersecting,
            get_part_geometry=lambda p: p.geometry,
            intersect_geometries=lambda g: boolean_manifold(
                g, operation="intersection", check_volume=False
            ).split(),  # pyright: ignore[reportUnknownMemberType]
            make_part_from_geometry=Part[Trimesh].from_geometry,
            make_assembly_from_parts=cls.from_parts,
        )

    @classmethod
    @override
    def _subtract_parts(
        cls: type[Self], to_be_subtracted: Part[Trimesh], to_subtract: Part[Trimesh]
    ) -> Self:
        from scadpy.core.part import Part, subtract_parts

