import numpy as np
from numpy.typing import NDArray

from scadpy.color.constants import BLACK

if TYPE_CHECKING:
    from scadpy.color import Color
    from scadpy.core.part import Part


class Assembly[G](ABC):
    def __init__(self, *args: Any, **kwargs: Any):  # pyright: ignore[reportExplicitAny, reportAny]
        super().__init__(*args, **kwargs)
        self._parts: Sequence[Part[G]] = []

    @cached_property
    def part_colors(self: Self) -> NDArray[np.float64]:
        from scadpy.core.assembly import get_assembly_part_colors

        return get_assembly_part_colors(self)

    @classmethod
    def from_parts(cls: type[Self], parts: Sequence[Part[G]]) -> Self:
        assembly = cls()
        assembly._parts = parts
        return assembly

    @classmethod
    def from_geometries(
        cls: type[Self], geometries: Sequence[G], color: Color = BLACK
    ) -> Self:
        from scadpy.core.part import Part

        return cls.from_parts(parts=[Part[G].from_geometry(g, color) for g in geometries])

    @classmethod
    def from_geometry(cls: type[Self], geometry: G, color: Color = BLACK) -> Self:
        return cls.from_geometries([geometry], color)

    ###################
    # transformations #
    ###################

    def color(self, color: Color) -> Self:
        from scadpy.core.assembly import color_assembly

        return color_assembly(
            self,
            color=color,
            get_assembly_parts=lambda a: a._parts,
            concat_parts=lambda p: self.from_parts(p),
        )

